    if opts.get("encrypt") and password is None:
        sys.stderr.write(f"{ERROR_PREFIX}Password must be provided when encrypting logs!\n")
        return 1
    if opts.get("decrypt") and password is None:
        sys.stderr.write(f"{ERROR_PREFIX}Password must be provided when decrypting logs!\n")
        return 1

