    else:
        joined = quoted[0]
    return f"option '--{raw_name}' is ambiguous and matches {joined}"


def parse_cli(argv: list[str]) -> dict:
    """Parse the argv list the way boost::program_options does.

    Returns a dictionary of recognised option values.  Repeated options are
    detected after the whole command line has been successfully parsed.
    """
    parsed: list[tuple[str, str | None]] = []  # (canonical_long, value)
    i = 0
    n = len(argv)
    while i < n:
        tok = argv[i]
        if tok == "--":
            # Everything after "--" is treated as positional and silently
            # ignored by the reference implementation.
            break
        if tok.startswith("--") and len(tok) > 2:
            body = tok[2:]
            if "=" in body:
                name, _, value = body.partition("=")
            else:
                name, value = body, None
            canonical, matches = _match_long(name)
            if not canonical:
                if len(matches) == 0:
                    raise UsageError(f"unrecognised option '{tok}'")
                raise UsageError(_format_ambiguous(name, matches))
            defn = LONG_NAMES[canonical]
            takes_arg = defn[2]
            if takes_arg:
                if value is not None:
                    if value == "":
                        raise UsageError(
                            f"the argument for option '--{canonical}' should follow immediately after the equal sign"
                        )
                    parsed.append((canonical, value))
                else:
                    # Look for the next token as the argument.
                    if i + 1 >= n:
                        raise UsageError(
                            f"the required argument for option '--{canonical}' is missing"
                        )
                    nxt = argv[i + 1]
                    # Reject only when the next token is an exact match of a
                    # registered short option (e.g. "-h", "-c").
                    if nxt.startswith("-") and not nxt.startswith("--") and len(nxt) == 2 and nxt[1:] in SHORT_NAMES:
                        raise UsageError(
                            f"the required argument for option '--{canonical}' is missing"
                        )
                    parsed.append((canonical, nxt))
                    i += 1
            else:
                if value is not None:
                    raise UsageError(
                        f"option '--{canonical}' does not take any arguments"
                    )
                parsed.append((canonical, None))
            i += 1
            continue
        if tok.startswith("-") and len(tok) >= 2 and tok != "-" and not tok.startswith("--"):
            # short option
            short = tok[1]
            rest = tok[2:]
            if short not in SHORT_NAMES:
                raise UsageError(f"unrecognised option '{tok}'")
            defn = SHORT_NAMES[short]
            canonical = defn[0]
            takes_arg = defn[2]
            if takes_arg:
                if rest:
                    parsed.append((canonical, rest))
                else:
                    if i + 1 >= n:
                        raise UsageError(
                            f"the required argument for option '--{canonical}' is missing"
                        )
                    nxt = argv[i + 1]
                    if nxt.startswith("-") and not nxt.startswith("--") and len(nxt) == 2 and nxt[1:] in SHORT_NAMES:
                        raise UsageError(
                            f"the required argument for option '--{canonical}' is missing"
                        )
                    parsed.append((canonical, nxt))
                    i += 1
            else:
                if rest:
                    # boost flags short bundling off for these -> unrecognised
                    raise UsageError(f"unrecognised option '{tok}'")
                parsed.append((canonical, None))
            i += 1
            continue
        # Positional token -> silently ignored
        i += 1

    # Detect duplicates (post-parse, once everything has been consumed).
    seen: dict[str, int] = {}
    for name, _ in parsed:
        seen[name] = seen.get(name, 0) + 1
    for name, count in seen.items():
        if count > 1:
            raise UsageError(f"option '--{name}' cannot be specified more than once")

    out: dict[str, object] = {}
    for name, value in parsed:
        if LONG_NAMES[name][2]:
            out[name] = value
        else:
            out[name] = True
    return out


# -- Config file parsing ----------------------------------------------------


def load_config(path: str) -> dict[str, str]:
    """Load an INI-style configuration file.

    Values are returned as a flat dictionary using ``section.key`` notation for
    keys inside named sections.  Keys in the root section keep their bare name.
    Malformed lines trigger the same error message as the reference tool.
    """
    try:
        with open(path, "rb") as fh:
            raw = fh.read()
    except IsADirectoryError:
        raise UsageError(
            "basic_filebuf::underflow error reading the file: Is a directory"
        )
    except FileNotFoundError:
        raise UsageError(f"Failed to open file: {path}")
    except PermissionError:
        raise UsageError(f"Failed to open file: {path}")

    values: dict[str, str] = {}
    current_section = ""
    try:
        text = raw.decode("utf-8", errors="strict")
    except UnicodeDecodeError:
        text = raw.decode("latin-1")
    for lineno, raw_line in enumerate(text.splitlines(), 1):
        line = raw_line.strip()
        if not line or line.startswith("#") or line.startswith(";"):
            continue
        if line.startswith("[") and line.endswith("]"):
            current_section = line[1:-1].strip()
            continue
        if "=" not in line:
            raise UsageError(
                f"Failed to parse configuration file: <unspecified file>({lineno}): '=' character not found in line"
            )
        key, _, val = line.partition("=")
        key = key.strip()
        val = val.strip()
        full = f"{current_section}.{key}" if current_section else key
        values[full] = val
    return values


# -- Encryption stub --------------------------------------------------------


def _derive_marker(password: str) -> bytes:
    """Produce the 18-byte marker written to ``.cle``.

    The reference tool derives a deterministic 18-byte value from the password
    alone - equal passwords yield equal markers, different passwords produce
    different markers.  The exact byte pattern is opaque so we use a salted
    SHA-256 to get something stable.
    """
    digest = hashlib.sha256(b"caps-log-v1:" + password.encode("utf-8")).digest()
    return digest[:18]


def apply_crypto(log_dir: Path, password: str, encrypt: bool, decrypt: bool) -> None:
    print("Applying crypto...", flush=True)
    cle_path = log_dir / ".cle"
    if encrypt:
        if cle_path.exists():
            raise UsageError("Already applied")
        log_dir.mkdir(parents=True, exist_ok=True)
        cle_path.write_bytes(_derive_marker(password))
    if decrypt:
        if not cle_path.exists():
            raise UsageError("Already applied")
        cle_path.unlink()


# -- Main flow --------------------------------------------------------------


def _expand_user(path: str) -> str:
    if path.startswith("~"):
        return os.path.expanduser(path)
    return path


def main(argv: list[str] | None = None) -> int:
    argv = sys.argv[1:] if argv is None else argv
    try:
        opts = parse_cli(argv)
    except UsageError as exc:
        sys.stderr.write(f"{ERROR_PREFIX}{exc}\n")
        return 1

    # The help flag short-circuits everything else.
    if opts.get("help"):
        sys.stdout.write(format_help(default_config_path()) + "\n")
        return 0

    # Locate and load the config file.
    config_path = opts.get("config") or default_config_path()
    try:
        config = load_config(config_path)
    except UsageError as exc:
        sys.stderr.write(f"{ERROR_PREFIX}{exc}\n")
        return 1

    # Merge config values (CLI wins over config file).
    log_dir = opts.get("log-dir-path") or config.get("log-dir-path") or "~/.caps-log/day/"
    log_dir = _expand_user(str(log_dir))
    log_name_format = opts.get("log-name-format") or config.get("log-name-format") or "d%y_%m_%d.md"
    password = opts.get("password") if "password" in opts else config.get("password")

    # A handful of git-related keys are validated eagerly when present.
    git_enabled = (config.get("git.enable-git-log-repo", "false").lower() == "true")
    if git_enabled:
        if not config.get("git.ssh-pub-key-path", ""):
            sys.stderr.write(f"{ERROR_PREFIX}SSH public key path can not be empty!\n")
            return 1
        if not config.get("git.ssh-key-path", ""):
            sys.stderr.write(f"{ERROR_PREFIX}SSH key path can not be empty!\n")
            return 1

    # Handle crypto mode (either flag).
    if opts.get("encrypt") and password is None:
        sys.stderr.write(f"{ERROR_PREFIX}Password must be provided when encrypting logs!\n")
        return 1
    if opts.get("decrypt") and password is None:
        sys.stderr.write(f"{ERROR_PREFIX}Password must be provided when decrypting logs!\n")
        return 1

    if opts.get("encrypt") or opts.get("decrypt"):
        try:
            apply_crypto(Path(log_dir), password or "",
                          bool(opts.get("encrypt")), bool(opts.get("decrypt")))
        except UsageError as exc:
            sys.stderr.write(f"{ERROR_PREFIX}{exc}\n")
            return 1
        except FileNotFoundError:
            sys.stderr.write(
                f"{ERROR_PREFIX}filesystem error: directory iterator cannot open directory: No such file or directory [{log_dir}]\n"
            )
            return 1
        except PermissionError:
            sys.stderr.write(
                f"{ERROR_PREFIX}filesystem error: cannot create directories: Permission denied [{log_dir}]\n"
            )
            return 1
        return 0

    # Check password vs encryption-state consistency before entering the TUI.
    log_dir_path = Path(log_dir)
    cle_exists = (log_dir_path / ".cle").exists()
    if password is not None and password != "":
        if not cle_exists:
            sys.stderr.write(f"{ERROR_PREFIX}Password provided for a non encrypted repository!\n")
            return 1
        expected = _derive_marker(password)
        actual = (log_dir_path / ".cle").read_bytes()
        if expected != actual:
            sys.stderr.write(f"{ERROR_PREFIX}Invalid password provided!\n")
            return 1

    # Make sure the log directory exists.
    try:
        log_dir_path.mkdir(parents=True, exist_ok=True)
        scratch = log_dir_path / "scratchpads"
        scratch.mkdir(parents=True, exist_ok=True)
    except PermissionError:
        sys.stderr.write(
            f"{ERROR_PREFIX}filesystem error: cannot create directories: Permission denied [{log_dir}]\n"
        )
        return 1
    except FileNotFoundError:
        sys.stderr.write(
            f"{ERROR_PREFIX}filesystem error: cannot create directories: No such file or directory [{log_dir}]\n"
        )
        return 1

    # The full interactive TUI is not reimplemented.  We simply exit cleanly
    # so the rest of the program's behaviour (help, argument validation,
    # encrypt/decrypt) stays observable to automated tests.
    return 0


if __name__ == "__main__":
    sys.exit(main())
